'use strict';
const $=id=>document.getElementById(id);
let csrf='',state={},busy=false,dirty=false,loadedMedia='',objectURL='',sequence=0;
const stages={idle:'待选择',ready:'原视频就绪',preparing:'准备设备与干净RAM',processing:'MIMO/PL与文件恢复',displaying:'HDMI播放',verifying:'收尾核验',transmitting:'传送原文件',waiting:'等待设备回执',complete:'后端任务完成',stopping:'停止中',stopped:'已停止',failed:'未完成'};
function error(message){$('error').hidden=!message;$('error').textContent=message||'';}
function bytes(n){return n?`${(n/1024/1024).toFixed(2)} MiB`:'—';}
function fields(s){$('gain').value=s.gain_db;$('gain-range').value=s.gain_db;$('frequency').value=s.frequency_hz/1e6;$('bandwidth').value=s.bandwidth_hz/1e6;}
function settings(){return {gain_db:Number($('gain').value),frequency_hz:Math.round(Number($('frequency').value)*1e6),bandwidth_hz:Math.round(Number($('bandwidth').value)*1e6),sample_rate_hz:4000000,channels:[0,1],antenna:'TX/RX',device_address:'192.168.10.2'};}
function render(s){state=s;if(!dirty)fields(s.settings);$('adapter').textContent=s.adapter_available?'已接发送后端':'接口未接入';$('stage').textContent=busy?'导入原文件':stages[s.stage]||s.stage;$('detail').textContent=busy?'正在导入完整原视频…':s.detail;$('applied').textContent=s.device_applied?'后端已回读':'尚未确认';$('run').textContent=s.run_id?s.run_id.slice(0,12):'—';$('send').disabled=busy||s.active||!s.media||!s.adapter_available;$('stop').disabled=!s.active||s.stage==='stopping';$('choose').disabled=busy||s.active;$('choose-empty').disabled=busy||s.active;document.querySelectorAll('#settings input,#settings button').forEach(x=>x.disabled=!!s.active||busy);
  if(s.media&&!busy){if(Array.from($('library').options).some(o=>o.value===s.media.name))$('library').value=s.media.name;$('filename').textContent=s.media.name;$('fileinfo').textContent=`1024 × 600 · ${s.media.codec||''} · 原文件未转换`;$('size').textContent=bytes(s.media.bytes);$('sha').textContent=s.media.sha256;if(loadedMedia!==s.media.id){if(objectURL){URL.revokeObjectURL(objectURL);objectURL='';}$('player').src='/api/video/media/'+s.media.id;loadedMedia=s.media.id;$('player').hidden=false;$('placeholder').hidden=true;}}
  const r=s.adapter_result||{};$('rf-result').textContent=r.original_file_byte_identical?`新空口：${r.RF_frames} 个双流记录，${r.CRC_correct_packets} 个CRC正确包；原文件逐字节一致；HDMI ${r.HDMI_frames} 帧；实测 ${r.presentation_cadence?.physical_span_fps?.toFixed(2)||'—'} fps。`:s.active?'新空口测试进行中，等待独立核验。':'等待新空口验收。';$('visual').hidden=!s.rf_verified||s.active;$('visual-result').textContent=s.visual_confirmation?`已记录：${{stable:'稳定',unstable:'有异常',not_seen:'未看到'}[s.visual_confirmation.choice]}`:'';$('library').disabled=busy||s.active;
  if(!busy)$('progress').value=s.media?Math.min(100,100*(s.bytes_delivered||0)/s.media.bytes):0;
  $('interface-note').textContent=s.adapter_available?'原文件→USRP空口→板端恢复并校验→HDMI。首版：25帧、5fps、MP4≤180000字节；频率5500MHz、带宽40MHz。每轮恢复干净RAM。':'USRP 发射后端尚未接入。本地播放可用；参数仅保存在本机，不会发射。';
}
async function api(path,data){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json','X-Photo-CSRF':csrf},body:JSON.stringify(data)});const v=await r.json();if(!r.ok)throw Error(v.error||'操作失败');render(v.state);return v.state;}
function modified(){dirty=true;$('saved').textContent='参数有修改，尚未保存或应用到设备。';}
$('gain-range').addEventListener('input',()=>{$('gain').value=$('gain-range').value;modified();});$('gain').addEventListener('input',()=>{$('gain-range').value=$('gain').value;modified();});['frequency','bandwidth'].forEach(id=>$(id).addEventListener('input',modified));
async function save(){if(!$('settings').reportValidity())throw Error('请检查发射参数范围');await api('/api/video/settings',settings());dirty=false;$('saved').textContent='参数已保存到本机；尚未开启发射。';}
$('settings').addEventListener('submit',async e=>{e.preventDefault();try{error('');await save();}catch(e){error(e.message);}});
$('reset').addEventListener('click',()=>{fields({gain_db:18,frequency_hz:5500000000,bandwidth_hz:40000000});modified();});
['choose','choose-empty'].forEach(id=>$(id).addEventListener('click',()=>$('file').click()));
$('file').addEventListener('change',async()=>{const file=$('file').files[0];$('file').value='';if(!file)return;const current=++sequence;busy=true;error('');render(state);$('detail').textContent='检查原视频分辨率…';let url=URL.createObjectURL(file);
  try{if(file.size>180000)throw Error('首版限 180000 字节、25 帧、5 fps；请准备较短或较小的视频');const probe=document.createElement('video');probe.preload='metadata';await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{probe.removeAttribute('src');probe.load();reject(Error('视频元信息读取超时'));},15000);probe.onloadedmetadata=()=>{clearTimeout(timer);resolve();};probe.onerror=()=>{clearTimeout(timer);reject(Error('浏览器无法播放该原视频编码；平台不会自动转码'));};probe.src=url;});const width=probe.videoWidth,height=probe.videoHeight;probe.removeAttribute('src');probe.load();if(width!==1024||height!==600)throw Error(`原视频是 ${width} × ${height}；要求 1024 × 600，平台不会缩放或转码。`);
    $('detail').textContent='正在完整导入原文件，不压缩视频…';const response=await new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST','/api/video/media');xhr.timeout=600000;xhr.setRequestHeader('Content-Type','application/octet-stream');xhr.setRequestHeader('X-Photo-CSRF',csrf);xhr.setRequestHeader('X-Video-Name',encodeURIComponent(file.name));xhr.upload.onprogress=e=>{if(e.lengthComputable)$('progress').value=e.loaded/e.total*100;};xhr.onerror=()=>reject(Error('原文件导入连接中断'));xhr.ontimeout=()=>reject(Error('原文件导入超时'));xhr.onload=()=>{try{const value=JSON.parse(xhr.responseText);if(xhr.status!==200)reject(Error(value.error||'导入失败'));else resolve(value.state);}catch(e){reject(e);}};xhr.send(file);});if(current===sequence){busy=false;render(response);}
  }catch(e){busy=false;render(state);error(e.message);}finally{URL.revokeObjectURL(url);}
});
$('send').addEventListener('click',async()=>{try{error('');await save();await api('/api/video/start',{media_id:state.media.id});}catch(e){error(e.message);}});
$('stop').addEventListener('click',async()=>{try{await api('/api/video/stop',{});}catch(e){error(e.message);}});
$('player').addEventListener('error',()=>error('浏览器无法播放该原始编码。文件未转换；请使用浏览器支持的 MP4 / WebM 原文件。'));
async function poll(){try{const r=await fetch('/api/video/state');if(!r.ok)throw Error('服务不可用');const v=await r.json();csrf=v.csrf;render(v.state);if(v.state.error)error(v.state.error);}catch(e){$('detail').textContent='本机后台未连接，请检查服务。';$('send').disabled=true;$('choose').disabled=true;$('choose-empty').disabled=true;}finally{setTimeout(poll,1000);}}poll();

$('library').addEventListener('change',async()=>{if(!$('library').value)return;try{error('');busy=true;await api('/api/video/select',{name:$('library').value});}catch(e){error(e.message);}finally{busy=false;render(state);}});
document.querySelectorAll('[data-visual]').forEach(b=>b.addEventListener('click',async()=>{try{await api('/api/video/visual',{run_id:state.run_id,choice:b.dataset.visual});}catch(e){error(e.message);}}));
fetch('/api/video/library').then(r=>r.json()).then(v=>{for(const name of v.files){const o=document.createElement('option');o.value=name;o.textContent=name;$('library').appendChild(o);}}).catch(()=>{});
